        d: "m231,265 1-2 3-1 1-1 -2,0 4-2 3-4 2-1 2,1 2-2 3-1 3,0 5,0 2,3 3,3 1,1 -3,1 4,1 2,2 0,1 -3-2 0,3 2,0 -1,2 -3,0 -3,3 -2,0 -6,0 0-2 -2,0 -2-3 -2,0 -2,1 1,1 -3,2 -3,0 -4-1 0-1zm8-51 4,0 2,0 -2,2 -1,0zm1,4 2,0 1,4 -2,0zm5-11 1-2 1,1 3,0 -1-2 7-3 1,2 -2,3 -3,1 2,1 -4,2 -4,3 -1-1 3-2 -3-1 1-1zm4,10 2,0 0-2 5-1 2,2 0,3 6,2 -4,3 -1-1 0-2 -4,0 -1-2 -4,0zm4,27 0-2 5-1 1,3 -1,1 -3,1 0-3zm1-20 1-1 1,2zm1,11 2-1 1-2 -3-1 1-1 2,0 2,1 3,1 0,2 -6,1zm3-6 3-1 2-1 -2-1 2-1 2-2 1-2 -2-2 -2-1 1-2 2,0 -2-2 2-3 6,0 -3-3 1-3 4,0 -1-2 0-2 2-1 3,1 3-1 1,1 3-1 10-1 3,0 3,0 -1,3 -1,2 -3,1 -8,4 -1,2 3,1 -3,2 -1,1 4,0 6-2 4,1 4-1 8,1 2-1 3,2 1,2 -3,3 -1,3 -2,3 -5,5 -2,1 -4,1 -2,1 4,0 3,1 -1,2 -3,0 -3,2 -2,0 -5,0 1,1 8,1 3-2 3,0 6,2 5,4 2,2 3,8 2,4 2,2 6,2 4,4 4,2 -1,2 1,2 3,4 -2,0 -3-2 -3,1 3,0 5,3 2,2 1,3 0,1 -4,3 3,2 2-1 2-2 7,0 4,1 4,2 1,2 0,3 -2,6 -3,2 -2,0 1,2 -2,0 -2,0 -3,1 2,1 0,2 -4,1 1,2 3,0 7,0 0,3 -5,2 -1,2 -3,0 -6,2 -2,0 -5,0 -4,0 -4,0 -9-2 1,2 -2,1 -5,0 -2,0 1,2 -1,0 -5-1 -2,1 -3-2 -3,0 -6,1 -1,2 -1,3 -3,2 -5-3 -8,2 -4,2 -1,2 -2,0 -3-1 -2,0 -1-1 1-1 4-1 4-3 6-5 1-3 3-1 1-2 5-1 6,1 4,0 9-9 -3,2 -4,1 -4,3 -4-1 -3-2 -2-1 -4,1 2-2 -4-1 -3,0 -4,2 -3-1 -2-3 2-2 3-1 7-2 3-2 2-3 -1-1 0-2 -1-2 0-1 -3,0 -4,2 0-2 3-2 1-1 3-2 4-1 3,0 4-1 3,2 -1-3 2,0 2,1 -2-2 0-2 2-2 -2,0 0-3 2,0 0-4 -4,1 -2-2 -3-3 -1-2 2-3 3-2 3-1 -5,0 -5,1 -3,2 -2,0 -2-1 -3,1 -4-1 -2,2 -3-2 0-2 1,0 2-3 4-5 -1-2 -2-1 0-3 1-1 3,0 -4-2 -3,1 -2,2 0-2 1-2 -3,2 0,3 -2,6 -2,1 -1-1 1-4 2-2 -1,0 0-4 1-3 2-4 3-4 -7,4 -3-1 -1-2zm1,13 0-1 2-1 -1-1 3-1 -3,5zm9,4 1-2 2,1 1,3 -3,0zm11,35 4-1 1,2 2,0 -4,2 -3-2zm16-86 2,0 1,1 -1,1zm1-1 0-3 4,1 0,1 4,1 -2,1 -1-1 -3,0 -1-1zm4,2 2,0 0,1zm0-7 1-1 3,2 -1,1 -1-2zm6,0 3-1 -2,2zm13-16 4-1 -1-2 -2,0 2-2 2,1 2,2 1,0 -2,6 -1,2 -1,0 1-3 -1-1 -2,0zm2,149 3-1 3,2 -2,1 -1,0zm5-154 1-2 0,4zm3-3 2,0 -1,2 -1,0z",
